    companion object {
        fun fromLanguageNum(num: Int): AppStrings = when (num) {
            1 -> ZhCnStrings
            2 -> ZhTwStrings
            3 -> JaStrings
            4 -> KoStrings
            5 -> RuStrings
            6 -> EsStrings
            7 -> TrStrings
            8 -> IdStrings
            9 -> FilStrings
            10 -> DeStrings
            11 -> ViStrings
            else -> EnStrings // 0 或默认 -> en-US
        }
    }
